{"command":"cat << 'EOF' > main.py
#!/usr/bin/env python3
import sys
import os
import json
import argparse
from pathlib import Path
from pygments.lexers.nix import NixLexer
from pygments.token import Token

def is_ident_token(t_type, t_val):
    if t_type in (Token.Text, Token.Text.Whitespace):
        return t_val.strip() != '' and not t_val.strip() in ['let', 'in', 'rec', 'inherit', 'with', 'if', 'then', 'else', 'assert', 'true', 'false', 'null', 'or']
    return False

def is_lambda_pattern(tokens, start_idx):
    idx = start_idx
    depth = 0
    while idx < len(tokens):
        val = tokens[idx][1]
        if val == '{': depth += 1
        elif val == '}':
            depth -= 1
            if depth == 0:
                idx += 1
                if idx < len(tokens):
                    if tokens[idx][1] == ':': return True
                    if tokens[idx][1] == '@': return True
                return False
        idx += 1
    return False

def parse_file(filepath, args):
    try:
        with open(filepath, 'r') as f:
            code = f.read()
    except Exception:
        return []

    code_lines = code.split('\n')
    lexer = NixLexer()
    tokens = []
    line = 1
    col = 1

    skip_lines = set()

    for t_type, t_val in lexer.get_tokens(code):
        if t_type in Token.Comment:
            if "deadnix: skip" in t_val:
                skip_lines.add(line + 1)

        if t_type not in (Token.Text.Whitespace, Token.Text) or t_val.strip() != '':
            val = t_val.strip() if t_type in (Token.Text, Token.Text.Whitespace) else t_val
            tokens.append((t_type, val, line, col, t_val)) # store original t_val for editing

        lines_t = t_val.split('\n')
        if len(lines_t) > 1:
            line += len(lines_t) - 1
            col = len(lines_t[-1]) + 1
        else:
            col += len(lines_t[0])

    tokens.append((Token.Keyword, 'EOF', line, col, ''))

    class Scope:
        def __init__(self, parent):
            self.parent = parent
            self.decls = {}
            self.usages = []
            self.sub = []
        def declare(self, name, l, c, t, s_tok, e_tok):
            if name not in self.decls:
                self.decls[name] = {"name": name, "line": l, "col": c, "type": t, "used": False, "start": s_tok, "end": e_tok}
        def add_usage(self, name):
            self.usages.append(name)
        def resolve(self):
            for u in self.usages:
                self._res(u)
            for s in self.sub:
                s.resolve()
        def _res(self, name):
            if name in self.decls:
                self.decls[name]["used"] = True
            elif self.parent:
                self.parent._res(name)

    root_scope = Scope(None)
    idx = 0

    def peek(offset=1):
        if idx + offset < len(tokens): return tokens[idx + offset][1]
        return 'EOF'

    def consume():
        nonlocal idx
        t = tokens[idx]
        idx += 1
        return t

    def parse_expr(stop, scope):
        nonlocal idx
        while idx < len(tokens) and tokens[idx][1] not in stop and tokens[idx][1] != 'EOF':
            t = tokens[idx]
            val = t[1]

            if val == '.':
                consume()
                if is_ident_token(tokens[idx][0], tokens[idx][1]):
                    consume()
            elif val == 'let':
                consume()
                s = Scope(scope)
                scope.sub.append(s)
                parse_bindings('in', s)
                consume()
                parse_expr(stop, s)
            elif val == 'rec':
                consume()
                if tokens[idx][1] == '{':
                    consume()
                    s = Scope(scope)
                    scope.sub.append(s)
                    parse_bindings('}', s)
                    consume()
            elif val == '{':
                if is_lambda_pattern(tokens, idx):
                    s = Scope(scope)
                    scope.sub.append(s)
                    parse_lambda_args(s)
                    if tokens[idx][1] == '@':
                        consume()
                        alias_t = consume()
                        s.declare(alias_t[1], alias_t[2], alias_t[3], 'alias', idx-2, idx-1)
                    if tokens[idx][1] == ':': consume()
                    parse_expr(stop, s)
                else:
                    consume()
                    parse_attrset('}', scope)
                    consume()
            elif is_ident_token(t[0], val) and peek() == ':':
                id_t = consume()
                consume()
                s = Scope(scope)
                scope.sub.append(s)
                s.declare(id_t[1], id_t[2], id_t[3], 'arg', idx-2, idx-1)
                parse_expr(stop, s)
            elif is_ident_token(t[0], val) and peek() == '@' and peek(2) == '{':
                id_t = consume()
                consume()
                s = Scope(scope)
                scope.sub.append(s)
                s.declare(id_t[1], id_t[2], id_t[3], 'alias', idx-2, idx-1)
                parse_lambda_args(s)
                if tokens[idx][1] == ':': consume()
                parse_expr(stop, s)
            elif is_ident_token(t[0], val):
                id_t = consume()
                scope.add_usage(id_t[1])
            elif val in ['(', '[']:
                start_val = consume()[1]
                end_val = ')' if start_val == '(' else ']'
                parse_expr([end_val], scope)
                if tokens[idx][1] == end_val: consume()
            elif val == '${':
                consume()
                parse_expr(['}'], scope)
                if tokens[idx][1] == '}': consume()
            else:
                consume()

    def parse_bindings(stop, scope):
        nonlocal idx
        while idx < len(tokens) and tokens[idx][1] != stop and tokens[idx][1] != 'EOF':
            if tokens[idx][1] == 'inherit':
                consume()
                from_expr = False
                if tokens[idx][1] == '(':
                    from_expr = True
                    consume()
                    parse_expr([')'], scope.parent)
                    if tokens[idx][1] == ')': consume()
                while idx < len(tokens) and tokens[idx][1] != ';':
                    if is_ident_token(tokens[idx][0], tokens[idx][1]):
                        id_t = consume()
                        scope.declare(id_t[1], id_t[2], id_t[3], 'let', idx-1, idx) # end will be fixed
                        if not from_expr: scope.parent.add_usage(id_t[1])
                    else:
                        consume()
                if tokens[idx][1] == ';': consume()
            else:
                start_tok = idx
                id_t = None
                if is_ident_token(tokens[idx][0], tokens[idx][1]):
                    id_t = consume()

                while idx < len(tokens) and tokens[idx][1] not in ('=', ';', 'EOF'):
                    if tokens[idx][1] == '.': consume()
                    elif is_ident_token(tokens[idx][0], tokens[idx][1]): consume()
                    elif tokens[idx][1] == '${':
                        consume()
                        parse_expr(['}'], scope)
                        if tokens[idx][1] == '}': consume()
                    else: consume()

                if tokens[idx][1] == '=': consume()
                parse_expr([';'], scope)
                end_tok = idx
                if tokens[idx][1] == ';': consume()

                if id_t:
                    scope.declare(id_t[1], id_t[2], id_t[3], 'let', start_tok, end_tok)

    def parse_attrset(stop, scope):
        nonlocal idx
        while idx < len(tokens) and tokens[idx][1] != stop and tokens[idx][1] != 'EOF':
            if tokens[idx][1] == 'inherit':
                consume()
                from_expr = False
                if tokens[idx][1] == '(':
                    from_expr = True
                    consume()
                    parse_expr([')'], scope)
                    if tokens[idx][1] == ')': consume()
                while idx < len(tokens) and tokens[idx][1] != ';':
                    if is_ident_token(tokens[idx][0], tokens[idx][1]):
                        id_t = consume()
                        if not from_expr: scope.add_usage(id_t[1])
                    else:
                        consume()
                if tokens[idx][1] == ';': consume()
            else:
                while idx < len(tokens) and tokens[idx][1] not in ('=', ';', 'EOF'):
                    if tokens[idx][1] == '.': consume()
                    elif is_ident_token(tokens[idx][0], tokens[idx][1]): consume()
                    elif tokens[idx][1] == '${':
                        consume()
                        parse_expr(['}'], scope)
                        if tokens[idx][1] == '}': consume()
                    else: consume()
                if tokens[idx][1] == '=': consume()
                parse_expr([';'], scope)
                if tokens[idx][1] == ';': consume()

    def parse_lambda_args(scope):
        nonlocal idx
        consume() # {
