        d = r['decl']
        start_tok = d['start_tok']
        end_tok = d['end_tok']

        if d['type'] == 'arg':
            # rename to _name
            tok = tokens[start_tok]
            tokens[start_tok] = (tok[0], tok[1], tok[2], tok[3], "_" + tok[4])
            continue

        if d['type'] in ('let', 'alias', 'pattern'):
            # simple heuristical token expansion
            # For alias `args @ {`:
            if d['type'] == 'alias':
                if start_tok > 0 and tokens[start_tok-1][1] == '}':
                    # { ... } @ args
                    start_tok -= 1
                    if tokens[start_tok][1] == '@': start_tok -= 1
                elif end_tok + 1 < len(tokens) and tokens[end_tok+1][1] == '@':
                    # args @ { ... }
                    end_tok += 1

            # For patterns `{ a, b }`:
            if d['type'] == 'pattern':
                if end_tok + 1 < len(tokens) and tokens[end_tok+1][1] == ',':
                    end_tok += 1
                elif start_tok > 0 and tokens[start_tok-1][1] == ',':
                    start_tok -= 1

            # consume trailing whitespace up to newline
            while end_tok + 1 < len(tokens) and tokens[end_tok+1][4].strip() == '':
                end_tok += 1
                if '\n' in tokens[end_tok][4]: break

            for i in range(start_tok, end_tok + 1):
                tokens[i] = (tokens[i][0], tokens[i][1], tokens[i][2], tokens[i][3], "")

    # Reconstruct code
    new_code = "".join(t[4] for t in tokens[:-1]) # exclude EOF
    with open(filepath, 'w') as f:
        f.write(new_code)
