#!/usr/bin/env python3
import sys
import os
import json
import argparse
from pathlib import Path
from pygments.lexers.nix import NixLexer
from pygments.token import Token

def is_ident_token(t_type, t_val):
    if t_type in (Token.Text, Token.Text.Whitespace):
        return t_val.strip() != '' and t_val.strip() not in ['let', 'in', 'rec', 'inherit', 'with', 'if', 'then', 'else', 'assert', 'true', 'false', 'null', 'or']
    return False

def is_lambda_pattern(tokens, start_idx):
    idx = start_idx
    depth = 0
    while idx < len(tokens):
        val = tokens[idx][1]
        if val == '{': depth += 1
        elif val == '}':
            depth -= 1
            if depth == 0:
                idx += 1
                if idx < len(tokens):
                    if tokens[idx][1] == ':': return True
                    if tokens[idx][1] == '@': return True
                return False
        idx += 1
    return False

def parse_file(filepath, args):
    try:
        with open(filepath, 'r') as f:
            code = f.read()
    except Exception:
        return [], [], []

    code_lines = code.split('\n')
    lexer = NixLexer()
    tokens = []
    line = 1
    col = 1

    skip_lines = set()

    for t_type, t_val in lexer.get_tokens(code):
        if t_type in Token.Comment:
            if "deadnix: skip" in t_val:
                skip_lines.add(line + 1)

        if t_type not in (Token.Text.Whitespace, Token.Text) or t_val.strip() != '':
            val = t_val.strip() if t_type in (Token.Text, Token.Text.Whitespace) else t_val
            tokens.append((t_type, val, line, col, t_val))

        lines_t = t_val.split('\n')
        if len(lines_t) > 1:
            line += len(lines_t) - 1
            col = len(lines_t[-1]) + 1
        else:
            col += len(lines_t[0])

    tokens.append((Token.Keyword, 'EOF', line, col, ''))

    class Scope:
        def __init__(self, parent):
            self.parent = parent
            self.decls = {}
            self.usages = []
            self.sub = []
        def declare(self, name, l, c, t, s_tok, e_tok):
            if name not in self.decls:
                self.decls[name] = {"name": name, "line": l, "col": c, "type": t, "used": False, "start": s_tok, "end": e_tok}
        def add_usage(self, name):
            self.usages.append(name)
        def resolve(self):
            for u in self.usages:
                self._res(u)
            for s in self.sub:
                s.resolve()
        def _res(self, name):
            if name in self.decls:
                self.decls[name]["used"] = True
            elif self.parent:
                self.parent._res(name)

    root_scope = Scope(None)
    idx = 0

    def peek(offset=1):
        if idx + offset < len(tokens): return tokens[idx + offset][1]
        return 'EOF'

    def consume():
        nonlocal idx
        t = tokens[idx]
        idx += 1
        return t

    def parse_expr(stop, scope):
        nonlocal idx
        while idx < len(tokens) and tokens[idx][1] not in stop and tokens[idx][1] != 'EOF':
            t = tokens[idx]
            val = t[1]

            if val == '.':
                consume()
                if is_ident_token(tokens[idx][0], tokens[idx][1]):
                    consume()
            elif val == 'let':
                consume()
                s = Scope(scope)
                scope.sub.append(s)
                parse_bindings('in', s)
                if tokens[idx][1] == 'in': consume()
                parse_expr(stop, s)
            elif val == 'rec':
                consume()
                if tokens[idx][1] == '{':
                    consume()
                    s = Scope(scope)
                    scope.sub.append(s)
                    parse_bindings('}', s)
                    if tokens[idx][1] == '}': consume()
            elif val == '{':
                if is_lambda_pattern(tokens, idx):
