                    scope.sub.append(s)
                    parse_lambda_args(s)
                    if tokens[idx][1] == '@':
                        consume()
                        alias_t = consume()
                        s.declare(alias_t[1], alias_t[2], alias_t[3], 'alias', idx-2, idx-1)
                    if tokens[idx][1] == ':': consume()
                    parse_expr(stop, s)
