                        consume()
                        parse_expr(['}'], scope)
                        if tokens[idx][1] == '}': consume()
                    else: consume()

                if tokens[idx][1] == '=': consume()
                parse_expr([';'], scope)
                end_tok = idx
                if tokens[idx][1] == ';': consume()

                if id_t:
                    scope.declare(id_t[1], id_t[2], id_t[3], 'let', start_tok, end_tok)

    def parse_attrset(stop, scope):
        nonlocal idx
        while idx < len(tokens) and tokens[idx][1] != stop and tokens[idx][1] != 'EOF':
            if tokens[idx][1] == 'inherit':
                consume()
                from_expr = False
                if tokens[idx][1] == '(':
                    from_expr = True
                    consume()
                    parse_expr([')'], scope)
                    if tokens[idx][1] == ')': consume()
                while idx < len(tokens) and tokens[idx][1] != ';':
