                        id_t = consume()
                        if not from_expr: scope.add_usage(id_t[1])
                    else:
                        consume()
                if tokens[idx][1] == ';': consume()
            else:
                while idx < len(tokens) and tokens[idx][1] not in ('=', ';', 'EOF'):
                    if tokens[idx][1] == '.': consume()
                    elif is_ident_token(tokens[idx][0], tokens[idx][1]): consume()
                    elif tokens[idx][1] == '${':
                        consume()
                        parse_expr(['}'], scope)
                        if tokens[idx][1] == '}': consume()
                    else: consume()
                if tokens[idx][1] == '=': consume()
                parse_expr([';'], scope)
                if tokens[idx][1] == ';': consume()

    def parse_lambda_args(scope):
        nonlocal idx
        consume() # {
        while idx < len(tokens) and tokens[idx][1] != '}' and tokens[idx][1] != 'EOF':
            if tokens[idx][1] == ',': consume()
            elif tokens[idx][1] == '.': consume()
            elif is_ident_token(tokens[idx][0], tokens[idx][1]):
                start_tok = idx
                id_t = consume()
                if tokens[idx][1] == '?':
                    consume()
                    parse_expr([',', '}'], scope)
                end_tok = idx - 1 if tokens[idx-1][1] != ',' else idx - 2
                scope.declare(id_t[1], id_t[2], id_t[3], 'pattern', start_tok, end_tok)
            else:
                consume()
        if tokens[idx][1] == '}': consume()

    parse_expr(['EOF'], root_scope)
    root_scope.resolve()

    results = []
    def collect(s):
        for name, d in s.decls.items():
            if not d["used"]:
                if d["line"] in skip_lines: continue
                if args.no_underscore and name.startswith('_'): continue
                if not args.no_underscore and d["type"] == 'arg' and name.startswith('_'): continue
                if args.no_lambda_arg and d["type"] == 'arg': continue
                if args.no_lambda_pattern_names and d["type"] == 'pattern': continue

                msg = ""
                if d["type"] == 'let': msg = f"Unused let binding: {name}"
                elif d["type"] == 'pattern': msg = f"Unused lambda pattern: {name}"
                elif d["type"] == 'alias': msg = f"Unused lambda pattern: {name}"
                elif d["type"] == 'arg': msg = f"Unused lambda argument: {name}"

                results.append({
                    "column": d["col"],
                    "endColumn": d["col"] + len(name),
                    "line": d["line"],
                    "message": msg,
                    "decl": d
                })
        for sub in s.sub:
            collect(sub)
    collect(root_scope)
    results.sort(key=lambda x: (x["line"], x["column"]))
    return results, code_lines, tokens

def apply_edits(filepath, results, tokens):
    results.sort(key=lambda x: x['decl']['start'], reverse=True)
    for r in results:
        d = r['decl']
        s_tok = d['start']
        e_tok = d['end']

        if d['type'] == 'arg':
            tok = tokens[s_tok]
            tokens[s_tok] = (tok[0], tok[1], tok[2], tok[3], "_" + tok[4])
