                    c_p = current_token_idx()
                    if tokens[c_p][1] == '.': consume()
                    elif is_ident_token(tokens[c_p][0], tokens[c_p][1]): consume()
                    elif tokens[c_p][1] == '${':
                        consume()
                        parse_expr(['}'], scope)
                        if peek() == '}': consume()
                    else: consume()

                if peek() == '=': consume()
                parse_expr([';'], scope)
                end_tok = current_token_idx()
                if peek() == ';': consume()

                if id_t:
                    scope.declare(id_t[1], id_t[2], id_t[3], 'let', start_tok, end_tok)

    def parse_attrset(stop, scope):
        nonlocal idx
        while idx < len(tokens):
            p = current_token_idx()
            if tokens[p][1] == stop or tokens[p][1] == 'EOF': break

            if tokens[p][1] == 'inherit':
                consume()
                from_expr = False
                if peek() == '(':
                    from_expr = True
                    consume()
                    parse_expr([')'], scope)
                    if peek() == ')': consume()
                while current_token_idx() < len(tokens) and tokens[current_token_idx()][1] != ';':
                    c_p = current_token_idx()
                    if is_ident_token(tokens[c_p][0], tokens[c_p][1]):
                        id_t = consume()
                        if not from_expr: scope.add_usage(id_t[1])
                    else:
                        consume()
                if peek() == ';': consume()
            else:
                while current_token_idx() < len(tokens) and tokens[current_token_idx()][1] not in ('=', ';', 'EOF'):
                    c_p = current_token_idx()
                    if tokens[c_p][1] == '.': consume()
                    elif is_ident_token(tokens[c_p][0], tokens[c_p][1]): consume()
                    elif tokens[c_p][1] == '${':
                        consume()
                        parse_expr(['}'], scope)
                        if peek() == '}': consume()
                    else: consume()
                if peek() == '=': consume()
                parse_expr([';'], scope)
                if peek() == ';': consume()

    def parse_lambda_args(scope):
        nonlocal idx
        while idx < len(tokens):
            p = current_token_idx()
            if tokens[p][1] == '}' or tokens[p][1] == 'EOF': break

            if tokens[p][1] == ',': consume()
            elif tokens[p][1] == '.': consume()
            elif is_ident_token(tokens[p][0], tokens[p][1]):
                start_tok = p
                id_t = consume()
                if peek() == '?':
                    consume()
                    parse_expr([',', '}'], scope)
                end_tok = current_token_idx() - 1
                scope.declare(id_t[1], id_t[2], id_t[3], 'pattern', start_tok, end_tok)
            else:
                consume()

    parse_expr(['EOF'], root_scope)
    root_scope.resolve()

    results = []
    def collect(s):
        for name, d in s.decls.items():
            if not d["used"]:
                if d["line"] in skip_lines: continue
                if args.no_underscore and name.startswith('_'): continue
                if not args.no_underscore and d["type"] == 'arg' and name.startswith('_'): continue
                if args.no_lambda_arg and d["type"] == 'arg': continue
                if args.no_lambda_pattern_names and d["type"] == 'pattern': continue

                msg = ""
                if d["type"] == 'let': msg = f"Unused let binding: {name}"
                elif d["type"] == 'pattern': msg = f"Unused lambda pattern: {name}"
                elif d["type"] == 'alias': msg = f"Unused lambda pattern: {name}"
                elif d["type"] == 'arg': msg = f"Unused lambda argument: {name}"

                results.append({
                    "column": d["col"],
                    "endColumn": d["col"] + len(name),
                    "line": d["line"],
                    "message": msg,
                    "decl": d
                })
        for sub in s.sub:
            collect(sub)
    collect(root_scope)
    results.sort(key=lambda x: (x["line"], x["column"]))
    return results, code_lines, tokens

def apply_edits(filepath, results, tokens):
    results.sort(key=lambda x: x['decl']['start'], reverse=True)
    for r in results:
        d = r['decl']
        s_tok = d['start']
        e_tok = d['end']

        if d['type'] == 'arg':
            tok = tokens[s_tok]
            tokens[s_tok] = (tok[0], tok[1], tok[2], tok[3], "_" + tok[4])
            continue

        if d['type'] in ('let', 'alias', 'pattern'):
            if d['type'] == 'alias':
                if s_tok > 0 and tokens[s_tok-1][1] == '}':
                    s_tok -= 1
                    if tokens[s_tok][1] == '@': s_tok -= 1
                elif e_tok + 1 < len(tokens) and tokens[e_tok+1][1] == '@':
                    e_tok += 1
            if d['type'] == 'pattern':
                if e_tok + 1 < len(tokens) and tokens[e_tok+1][1] == ',':
                    e_tok += 1
                elif s_tok > 0 and tokens[s_tok-1][1] == ',':
                    s_tok -= 1

            while e_tok + 1 < len(tokens) and tokens[e_tok+1][4].strip() == '':
                e_tok += 1
                if '\n' in tokens[e_tok][4]: break

            for i in range(s_tok, e_tok + 1):
                tokens[i] = (tokens[i][0], tokens[i][1], tokens[i][2], tokens[i][3], "")

    new_code = "".join(t[4] for t in tokens[:-1])
    with open(filepath, 'w') as f:
        f.write(new_code)

if __name__ == '__main__':
    parser = argparse.ArgumentParser(prog='deadnix', add_help=False)
    parser.add_argument('file_paths', nargs='*', default=['.'])
    parser.add_argument('-l', '--no-lambda-arg', action='store_true')
    parser.add_argument('-L', '--no-lambda-pattern-names', action='store_true')
    parser.add_argument('-_', '--no-underscore', action='store_true')
    parser.add_argument('-q', '--quiet', action='store_true')
    parser.add_argument('-e', '--edit', action='store_true')
    parser.add_argument('-h', '--hidden', action='store_true')
    parser.add_argument('--help', action='store_true')
    parser.add_argument('-f', '--fail', action='store_true')
    parser.add_argument('-o', '--output-format', default='human-readable', choices=['human-readable', 'json'])
    parser.add_argument('--exclude', nargs='*', default=[])
    parser.add_argument('-V', '--version', action='store_true')

    argv = sys.argv[1:]
    if '-_' in argv:
        argv[argv.index('-_')] = '--no-underscore'

    args = parser.parse_args(argv)

    if args.version:
        print("deadnix 1.2.1")
        sys.exit(0)
    if args.help:
        print("Find dead code in .nix files\n\nUsage: deadnix [OPTIONS] [FILE_PATHS]...")
        sys.exit(0)

    files = []
    for p in args.file_paths:
        path = Path(p)
        if path.is_file() and path.name.endswith('.nix'):
            files.append(path)
        elif path.is_dir():
            for root, dirs, fnames in os.walk(path):
                if not args.hidden:
                    dirs[:] = [d for d in dirs if not d.startswith('.')]
                for fname in fnames:
                    if fname.endswith('.nix'):
                        if not args.hidden and fname.startswith('.'): continue
                        files.append(Path(root) / fname)

    has_unused = False

    for f in files:
        skip = False
        for ex in args.exclude:
            if ex in str(f):
                skip = True
                break
        if skip: continue

        res, code_lines, tokens = parse_file(str(f), args)
        if res:
            has_unused = True

            if args.output_format == 'json':
                out_res = [{"column": r["column"], "endColumn": r["endColumn"], "line": r["line"], "message": r["message"]} for r in res]
                print(json.dumps({"file": str(f), "results": out_res}, separators=(',', ':')))
            elif not args.quiet:
                print(f"\033[33mWarning:\033[0m Unused declarations were found.")
                for r in res:
                    print(f"    \033[38;5;246m╭─[{str(f)}:{r['line']}:{r['column']}]\033[0m")
                    print(f" \033[38;5;246m{r['line']:2} │\033[0m {code_lines[r['line']-1]}")
                    pad = " " * (r['column'] - 1)
                    arr = "╰" + "─" * max(0, r['endColumn'] - r['column'] - 1)
                    print(f" \033[38;5;240m   │\033[0m {pad}\033[31m{arr}\033[0m {r['message']}")

            if args.edit:
                apply_edits(str(f), res, tokens)

    if args.fail and has_unused:
        sys.exit(1)
